def find_path(graph, start, goal):
    open_set = set([start])
    closed_set = set()
    parent = {}
    path = []
    found = False
    while not found and open_set:
        current = None
        current_cost = float('inf')
        for node in open_set:
            if node in graph and graph[node] and (graph[node][0] < current_cost):
                current = node
                current_cost = graph[node][0]
        if current == goal:
            found = True
        else:
            closed_set.add(current)
            for neighbor in graph[current]:
                if neighbor not in closed_set:
                    open_set.add(neighbor)
                    parent[neighbor] = current
                    graph[neighbor][0] = graph[current][0] + neighbor
                    if neighbor == goal:
                        found = True
                        break
    if not found:
        return None
    current = goal
    while current != start:
        path.append(current)
        current = parent[current]
    path.append(start)
    path.reverse()
    return path

